<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignment\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\UserRoleAssignmentRef;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Application\Service\Visibility\UserRoleAssignmentVisibilityService;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserRoleAssignmentUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserRoleAssignmentVisibilityService $visibility,
        private readonly UserRoleAssignmentWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?UserRoleAssignmentRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for User role assignment");
        $span = $this->startSpan("Check allow update usecase for User role assignment");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignmentUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?UserRoleAssignmentRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for User role assignment");
        $span = $this->startSpan("Check fixed fields for update usecase for User role assignment");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, UserRoleAssignmentUpdateParams $params): UserRoleAssignmentUpdateResult
    {
        $this->logDebug("Run update usecase for User role assignment");
        $span = $this->startSpan("Run update usecase for User role assignment");
        try {
            $ref = new UserRoleAssignmentRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update User role assignment');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new UserRoleAssignmentUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new UserRoleAssignmentUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserRoleAssignmentUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
